function heal(){let p=state.player;if(p.healCd>0||state.dead||state.paused)return;if(p.hp>=p.maxHp){showToast('Your vitality is already whole.');return}p.hp=Math.min(p.maxHp,p.hp+35);p.healCd=12;particle(p.x,p.y,'#c75e55',18,55);floater(p.x,p.y-25,'+35 VITALITY','#e98b75');sound(520,.25)}
function update(dt){if(state.paused||state.dead)return;state.elapsed+=dt;state.t+=dt;let p=state.player,s=totalStats();if(lastToast>0){lastToast-=dt;if(lastToast<=0)$('toast').classList.remove('show')}
 p.dashCd=Math.max(0,p.dashCd-dt);p.healCd=Math.max(0,p.healCd-dt);p.regen>0&&(p.hp=Math.min(s.maxHp,p.hp+s.regen*dt));
 let dx=(state.keys.d||state.keys.ArrowRight?1:0)-(state.keys.a||state.keys.ArrowLeft?1:0),dy=(state.keys.s||state.keys.ArrowDown?1:0)-(state.keys.w||state.keys.ArrowUp?1:0);if(state.aim){let ax=state.aim.x-p.x,ay=state.aim.y-p.y,m=Math.hypot(ax,ay);if(m>12){dx=ax/m;dy=ay/m}else state.aim=null}let mag=Math.hypot(dx,dy);if(mag){dx/=Math.max(1,mag);dy/=Math.max(1,mag);p.dir=Math.atan2(dy,dx)}if(p.dash>0){p.dash-=dt;p.x+=p.dashX*560*dt;p.y+=p.dashY*560*dt}else{p.x+=dx*s.speed*dt;p.y+=dy*s.speed*dt}p.x=clamp(p.x,17,state.w-17);p.y=clamp(p.y,17,state.h-17);
 state.spawn-=dt;if(state.spawn<=0){spawnEnemy();state.spawn=Math.max(.22,1.05-state.elapsed*.004)*(state.enemies.length>45?2:1)}
 p.attack-=dt;if(p.attack<=0){let e=nearestEnemy();if(e&&Math.hypot(e.x-p.x,e.y-p.y)<370){let a=Math.atan2(e.y-p.y,e.x-p.x),speed=420;state.orbs.push({x:p.x+Math.cos(a)*17,y:p.y+Math.sin(a)*17,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,damage:s.damage+s.might*.35,r:4,life:.8,bolt:true,trail:[]});p.attack=s.cooldown; p.dir=a;sound(660,.035,'sine')}else p.attack=Math.min(p.attack,.08)}
 for(let e of state.enemies){if(e.dead)continue;let ex=p.x-e.x,ey=p.y-e.y,d=Math.hypot(ex,ey)||1;if(d>p.r+e.r+2){e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt}else{e.attack-=dt;if(e.attack<=0&&p.dash<=0){let dmg=Math.max(1,e.damage-s.armor*.65);p.hp-=dmg;e.attack=.8;state.shake=5;floater(p.x,p.y-16,'-'+Math.round(dmg),'#e37b63');particle(p.x,p.y,'#b84c43',5,45);if(p.hp<=0){p.hp=0;endGame()}}}e.phase+=dt*3;e.flash=Math.max(0,e.flash-dt)}
 state.enemies=state.enemies.filter(e=>!e.dead);
 for(let o of state.orbs){o.life-=dt;if(o.bolt){o.x+=o.vx*dt;o.y+=o.vy*dt;o.trail.push({x:o.x,y:o.y});if(o.trail.length>5)o.trail.shift();for(let e of state.enemies){if(!e.dead&&Math.hypot(e.x-o.x,e.y-o.y)<e.r+o.r+3){e.hp-=o.damage;e.flash=.12;o.life=0;particle(o.x,o.y,'#d7c38a',4,24);if(e.hp<=0)killEnemy(e);break}}}else{let d=Math.hypot(p.x-o.x,p.y-o.y);if(d<s.magnet+30&&d>2){let pull=d<s.magnet?1.8:0.65;o.x+=(p.x-o.x)/d*(120+pull*90)*dt;o.y+=(p.y-o.y)/d*(120+pull*90)*dt}if(d<20){o.life=0;state.xp+=o.value;particle(o.x,o.y,'#e1c978',5,34);sound(820,.045);while(state.xp>=state.xpNeed){state.xp-=state.xpNeed;state.level++;state.xpNeed=Math.floor(state.xpNeed*1.35+4);showLevelChoice()}}} }
 state.orbs=state.orbs.filter(o=>o.life>0);
 for(let d of state.drops){d.life-=dt;d.bob+=dt*3;let distance=Math.hypot(p.x-d.x,p.y-d.y);if(distance<29){claimDrop(d);d.life=0}}
 state.drops=state.drops.filter(d=>d.life>0);
 for(let a of state.particles){a.x+=a.vx*dt;a.y+=a.vy*dt;a.vx*=Math.pow(.08,dt);a.vy*=Math.pow(.08,dt);a.life-=dt}state.particles=state.particles.filter(a=>a.life>0);
 for(let f of state.floaters){f.y-=25*dt;f.life-=dt}state.floaters=state.floaters.filter(f=>f.life>0);state.shake*=Math.pow(.02,dt);updateUI();
}
function draw(){let w=state.w,h=state.h;ctx.clearRect(0,0,w,h);ctx.save();if(state.shake>0)ctx.translate(rand(-state.shake,state.shake),rand(-state.shake,state.shake));let bg=ctx.createLinearGradient(0,0,w,h);bg.addColorStop(0,'#1d2823');bg.addColorStop(.55,'#26312a');bg.addColorStop(1,'#17201d');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
 // worn flagstones and fine engraved paths
 const tile=68,ox=(state.player.x*.16)%tile,oy=(state.player.y*.16)%tile;for(let y=-tile;y<h+tile;y+=tile)for(let x=-tile;x<w+tile;x+=tile){let gx=x-ox,gy=y-oy;let id=(Math.floor((x+1200)/tile)*7+Math.floor((y+900)/tile)*13)%5;ctx.fillStyle=['#ffffff05','#00000008','#ffffff03','#00000004','#ffffff02'][Math.abs(id)];ctx.fillRect(gx+2,gy+2,tile-4,tile-4);ctx.strokeStyle='#080d0c45';ctx.lineWidth=1;ctx.strokeRect(gx+2,gy+2,tile-4,tile-4);if(id===0){ctx.strokeStyle='#b8a77c12';ctx.beginPath();ctx.moveTo(gx+13,gy+19);ctx.lineTo(gx+25,gy+31);ctx.lineTo(gx+19,gy+42);ctx.stroke()}}
 // ruins along edges
 for(let i=0;i<8;i++){let x=i*(w/7)+Math.sin(i*12)*22;let y=(i%2?18:h-20);ctx.fillStyle='#0c100f';ctx.beginPath();ctx.ellipse(x,y,rand(18,30),rand(7,12),0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#32362e';ctx.fillRect(x-8,y-28,16,30);ctx.fillStyle='#565344';ctx.fillRect(x-13,y-31,26,5);ctx.fillStyle='#252a25';ctx.fillRect(x-5,y-25,10,26)}
 // moss, candles and gravestones, camera-anchored decoration
 for(let i=0;i<28;i++){let x=(i*173+91- state.player.x*.11)%(w+100);if(x<0)x+=w+100;x-=50;let y=(i*239+47-state.player.y*.11)%(h+80);if(y<0)y+=h+80;y-=40;if(i%4===0){ctx.fillStyle='#111513';ctx.fillRect(x-8,y-7,16,14);ctx.fillStyle='#4b4c3b';ctx.fillRect(x-6,y-5,12,10);ctx.fillStyle='#d2a35a';ctx.globalAlpha=.5+Math.sin(state.t*3+i)*.15;ctx.beginPath();ctx.ellipse(x,y-5,2,4,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}else{ctx.fillStyle=i%2?'#303a2e':'#242d27';ctx.beginPath();ctx.ellipse(x,y,rand(5,11),rand(3,7),rand(0,3),0,Math.PI*2);ctx.fill()}}
 // enemy warning mist and actors
 for(let e of state.enemies)drawEnemy(e);
 for(let o of state.orbs){if(o.bolt){for(let i=0;i<o.trail.length;i++){ctx.globalAlpha=(i+1)/o.trail.length*.35;ctx.fillStyle='#d5c58b';ctx.beginPath();ctx.arc(o.trail[i].x,o.trail[i].y,o.r*(i+1)/o.trail.length,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.fillStyle='#fff0b0';ctx.shadowColor='#eed58a';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(o.x,o.y,o.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}else{let pulse=1+Math.sin(state.t*4+o.phase)*.18;ctx.fillStyle='#e2d087';ctx.shadowColor='#bb9e55';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(o.x,o.y,o.r*pulse,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff4c4';ctx.beginPath();ctx.arc(o.x-1,o.y-1,1.4,0,Math.PI*2);ctx.fill()}}
 for(let d of state.drops)drawDrop(d);
 drawPlayer();for(let a of state.particles){ctx.globalAlpha=clamp(a.life/a.max,0,1);ctx.fillStyle=a.color;ctx.beginPath();ctx.arc(a.x,a.y,a.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(let f of state.floaters){ctx.globalAlpha=clamp(f.life,0,1);ctx.fillStyle=f.color;ctx.font='bold 11px Arial';ctx.textAlign='center';ctx.shadowColor='#000';ctx.shadowBlur=4;ctx.fillText(f.text,f.x,f.y);ctx.shadowBlur=0}ctx.globalAlpha=1;ctx.restore();requestAnimationFrame(frame)}

