function frame(now){let dt=Math.min(.04,(now-state.last)/1000||0);state.last=now;update(dt);draw()}
function showLevelChoice(){state.paused=true;let picks=[...blessings].sort(()=>Math.random()-.5).slice(0,3);$('choiceLevel').textContent=String(state.level).padStart(2,'0');$('choices').innerHTML='';for(const b of picks){let el=document.createElement('button');el.className='choice';el.innerHTML=`<em>BLESSING</em><div class="choice-icon">${b.icon}</div><div><b>${b.name}</b><p>${b.desc}</p></div>`;el.onclick=()=>{b.apply(state.player);state.paused=false;$('levelOverlay').classList.remove('open');showToast(b.name+' bestowed');sound(700,.2)};$('choices').appendChild(el)}$('levelOverlay').classList.add('open');sound(440,.2)}
function claimDrop(d){let it=d.item,old=state.gear[it.slot];state.gear[it.slot]=it;let s=it.rarity==='legendary'?'LEGENDARY':it.rarity.toUpperCase();state.recent.unshift(it);state.recent=state.recent.slice(0,8);if(old)showToast('RELIC REPLACED · '+it.name);else showToast(s+' RELIC · '+it.name);particle(d.x,d.y,it.rarity==='legendary'?'#ff9b4e':it.rarity==='rare'?'#ffe16e':'#8fc5ff',18,75);sound(900,.2);updateUI()}
function updateUI(){let p=state.player,s=totalStats(),time=Math.floor(state.elapsed),m=String(Math.floor(time/60)).padStart(2,'0'),ss=String(time%60).padStart(2,'0');$('timer').textContent=m+':'+ss;$('kills').textContent=String(state.kills).padStart(3,'0');$('level').textContent=String(state.level).padStart(2,'0');$('sideLevel').textContent=String(state.level).padStart(2,'0');$('xpFill').style.width=(state.xp/state.xpNeed*100)+'%';$('hpText').textContent=Math.ceil(p.hp)+' / '+Math.round(s.maxHp);$('hpFill').style.width=(p.hp/s.maxHp*100)+'%';$('statMight').textContent=Math.round(s.might);$('statArmor').textContent=Math.round(s.armor);$('statSpeed').textContent=Math.round(s.speed/1.5*100)+'%';$('statLuck').textContent=Math.round(s.luck)+'%';$('statDamage').textContent=Math.round(s.damage+s.might*.35);$('statRegen').textContent=s.regen.toFixed(1)+'/s';$('objective').textContent=state.elapsed<60?'Survive the night · '+(60-Math.floor(state.elapsed))+'s':'The Hollow grows restless';
 let slots=[['Weapon','†'],['Chest','♜'],['Ring','◉'],['Boots','⌁']];$('gearGrid').innerHTML=slots.map(([slot,icon])=>{let it=state.gear[slot];return `<div class="gear-slot" title="${it?it.name+' — '+it.desc:'Empty '+slot+' slot'}"><div class="gear-icon ${it?'rarity-'+it.rarity:''}">${it?it.icon:icon}</div><div class="gear-label"><small>${slot.toUpperCase()}</small><b class="${it?'rarity-'+it.rarity:''}">${it?it.name:'Empty'}</b></div></div>`}).join('');$('lootCount').textContent=state.recent.length+' / 8';$('lootList').innerHTML=state.recent.length?state.recent.slice(0,5).map(it=>`<div class="loot-row"><span class="loot-icon rarity-${it.rarity}">${it.icon}</span><div><b class="rarity-${it.rarity}">${it.name}</b><small>${it.slot} · ${it.desc}</small></div></div>`).join(''):'<div class="loot-empty">The dark has yielded nothing… yet.</div>';
 $('dashSkill').classList.toggle('cooling',p.dashCd>0);$('dashSkill').querySelector('.cool').style.height=(p.dashCd/3.2*100)+'%';$('healSkill').classList.toggle('cooling',p.healCd>0);$('healSkill').querySelector('.cool').style.height=(p.healCd/12*100)+'%';$('pickupHint').classList.toggle('show',state.drops.some(d=>Math.hypot(d.x-p.x,d.y-p.y)<100))}
function pause(){if(state.dead)return;state.paused=!state.paused;$('pauseOverlay').classList.toggle('open',state.paused);$('pauseBtn').textContent=state.paused?'▶':'Ⅱ'}
function endGame(){state.dead=true;$('endTime').textContent=$('timer').textContent;$('endKills').textContent=state.kills;$('endLevel').textContent=state.level;$('deathOverlay').classList.add('open');sound(100,.65,'sawtooth')}
